#include <optional>
#include <sstream>
#include <string>
#include <vector>

struct Spawn { char kind; int x; int y; };
struct Level
{
    int width{ 0 }, height{ 0 };
    std::string tiles;             // row-major, only # . + >
    int playerX{ 0 }, playerY{ 0 };
    std::vector<Spawn> spawns;
};

std::optional<Level> parseLevel(const std::string& text)
{
    Level level;
    int players{ 0 };
    std::istringstream in{ text };
    std::string line;
    while (std::getline(in, line))
    {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.empty() || line.rfind("# ", 0) == 0) continue;
        if (level.height == 0) level.width = static_cast<int>(line.size());
        else if (static_cast<int>(line.size()) != level.width) return std::nullopt;
        for (int x{ 0 }; x < level.width; ++x)
        {
            const char c{ line[static_cast<std::size_t>(x)] };
            switch (c)
            {
            case '#': case '.': case '+': case '>': level.tiles += c; break;
            case '@': ++players; level.playerX = x; level.playerY = level.height; level.tiles += '.'; break;
            case 'g': case 'k': case 't': level.spawns.push_back({ c, x, level.height }); level.tiles += '.'; break;
            default: return std::nullopt;
            }
        }
        ++level.height;
    }
    if (level.height == 0 || players != 1) return std::nullopt;
    return level;
}

hints:
A `std::istringstream` (from `<sstream>`) lets you read a string the way you read `std::cin`. `std::getline` then hands you one line at a time:

```cpp
std::istringstream in{ text };
std::string line;
while (std::getline(in, line)) { /* one line, without the '\n' */ }
```

unitTests:
TEST("a small level")
{
    const auto l{ parseLevel("#####
#@.g#
#####
") };
    CHECK(l.has_value());
    CHECK_EQ(l->width, 5); CHECK_EQ(l->height, 3);
    CHECK_EQ(l->tiles, std::string("######...######"));
    CHECK_EQ(l->playerX, 1); CHECK_EQ(l->playerY, 1);
    CHECK_EQ(l->spawns.size(), std::size_t{ 1 });
    CHECK_EQ(l->spawns[0].kind, 'g'); CHECK_EQ(l->spawns[0].x, 3); CHECK_EQ(l->spawns[0].y, 1);
}
TEST("comments, blank lines and CRLF") { const auto l{ parseLevel("# floor one

###
#@>
###
") }; CHECK(l.has_value()); CHECK_EQ(l->height, 3); CHECK_EQ(l->tiles, std::string("####.>###")); }
TEST("spawns in reading order") { const auto l{ parseLevel("t.g
.@.
k..
") }; CHECK_EQ(l->spawns.size(), std::size_t{ 3 }); CHECK_EQ(l->spawns[0].kind, 't'); CHECK_EQ(l->spawns[1].kind, 'g'); CHECK_EQ(l->spawns[2].kind, 'k'); CHECK_EQ(l->spawns[2].y, 2); }
TEST("doors and stairs") { const auto l{ parseLevel("@+>
") }; CHECK_EQ(l->tiles, std::string(".+>")); }
TEST("ragged rows") { CHECK(!parseLevel("####
#@.
####
").has_value()); }
TEST("unknown characters") { CHECK(!parseLevel("##
@x
").has_value()); }
TEST("no player or two players") { CHECK(!parseLevel("###
#.#
").has_value()); CHECK(!parseLevel("@@
").has_value()); }
TEST("nothing at all") { CHECK(!parseLevel("").has_value()); CHECK(!parseLevel("# only a comment
").has_value()); }

